package org.sleepwell.app;

import android.app.Activity;import android.content.*;import android.os.Bundle;import android.widget.*;import java.time.*;import java.time.format.DateTimeFormatter;import java.util.*;import java.util.concurrent.*;import java.util.function.Supplier;

/** Saved-record descriptive flow; no sensor/service/network work or implicit record edits. */
public final class RecordInsightsActivity extends Activity {
    static Supplier<Instant> clock=Instant::now;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private SharedPreferences settings;private RecordInsights data;private String error="";private LocalDate anchor;private int days=30,metric,generation;private boolean chosen,loading;
    @Override public void onCreate(Bundle state){super.onCreate(state);RecordUi.review(this);settings=RecordInsightSettings.factory.open(this);if(state!=null){days=state.getInt("days",30);metric=Math.max(0,Math.min(2,state.getInt("metric")));chosen=state.getBoolean("chosen");String date=state.getString("anchor");if(date!=null)anchor=LocalDate.parse(date);}else try{String date=getIntent().getStringExtra("anchor");if(date!=null)anchor=LocalDate.parse(date);}catch(DateTimeException ignored){}render();}
    @Override protected void onResume(){super.onResume();load(false);}
    private void load(boolean save){int request=++generation;loading=true;error="";render();Records.Factory records=Records.factory;SleepPlans.Repository plans=SleepPlans.repository(this);Supplier<Instant> sourceClock=clock;int selected=days;boolean useSaved=!chosen;LocalDate requested=anchor;long record=getIntent().getLongExtra("record",0);int cutoff=RecordInsightSettings.cutoff.read(this);worker.execute(()->{try(Store store=records.open(getApplicationContext())){int window=useSaved?RecordInsightSettings.days(settings):selected;if(save)RecordInsightSettings.save(settings,window);if(store.rows("SELECT COUNT(*) AS n FROM sessions").get(0).optLong("n")>3000||store.rows("SELECT COUNT(*) AS n FROM tracking_pauses").get(0).optLong("n")>20000)throw new IllegalStateException("This history is too large for this insight view. Your records are kept.");Instant now=sourceClock.get();LocalDate today=SleepDay.label(now.toEpochMilli(),ZoneId.systemDefault(),cutoff);LocalDate end=requested;if(end==null&&record>0)end=Records.get(store,record).day(cutoff);if(end==null||end.isAfter(today))end=today;List<GoalCommitment> goals;try{goals=plans.goals();}catch(RuntimeException unreadable){goals=null;}RecordInsights result=new RecordInsights(Records.all(store),goals,end,window,cutoff,now);LocalDate frozen=end;runOnUiThread(()->{if(isDestroyed()||request!=generation)return;days=window;anchor=frozen;data=result;loading=false;render();});}catch(Exception failure){runOnUiThread(()->{if(isDestroyed()||request!=generation)return;loading=false;error=failure instanceof IllegalArgumentException||failure instanceof IllegalStateException?failure.getMessage():"Saved insights could not be opened. Your records are kept.";if(error==null||error.isBlank())error="Saved insights could not be opened.";render();});}});}
    private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Recorded insights",this::finish);Design.space(body,8);if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(body,"Retry insights",true,()->load(false));Design.button(body,"Use 30-day view",false,()->{days=30;chosen=true;load(true);});return;}if(data==null){Design.text(body,"Reading saved periods…",14,400,Design.MUTED);return;}String range=data.range.start.format(DateTimeFormatter.ofPattern("d MMM",Locale.getDefault()))+" – "+data.range.end.format(DateTimeFormatter.ofPattern("d MMM uuuu",Locale.getDefault()));Design.text(body,range,13,400,Design.MUTED);Design.space(body,8);LinearLayout windows=RecordUi.segments(body,new String[]{"7 days","30 days","90 days"},RecordInsights.WINDOWS.indexOf(days),index->{if(loading)return;days=RecordInsights.WINDOWS.get(index);chosen=true;load(true);});RecordUi.enabled(windows,!loading);Design.space(body,12);
        Design.text(body,data.observed+" of "+data.days.size()+" days recorded",25,600,Design.INK).setContentDescription("Insight coverage "+data.observed+" of "+data.days.size()+" days");Design.text(body,data.missing+" missing dates · no zero-sleep estimate",13,400,Design.MUTED);if(loading)Design.text(body,"Updating…",12,400,Design.MUTED);
        if(data.observed==0){Design.space(body,24);Design.text(body,"No completed periods in this range",20,600,Design.INK);Design.button(body,"Review saved records",true,()->startActivity(RecordUi.intent(this,HistoryActivity.class)));Design.button(body,"Add a remembered period",false,()->startActivity(RecordUi.intent(this,RecordEditorActivity.class)));return;}
        RecordUi.heading(body,"Daily recorded duration");Design.text(body,RecordUi.duration(data.average),38,700,Design.INK).setContentDescription("Average recorded duration "+RecordUi.duration(data.average));Design.text(body,"Median "+RecordUi.duration(data.median)+" · Range "+RecordUi.duration(data.minimum)+"–"+RecordUi.duration(data.maximum),12,400,Design.MUTED);
        Design.space(body,12);RecordUi.segments(body,new String[]{"Duration","Goal balance","Start time"},metric,index->{metric=index;render();});Design.space(body,8);body.addView(new RecordInsightsChart(this,data,metric),new LinearLayout.LayoutParams(-1,Design.dp(this,184)));Design.text(body,metric==0?"Paused and marked-awake time excluded. Missing dates stay blank.":metric==1?"Only closed dates with saved duration goals. Their original zone and day boundary apply.":"Longest non-nap recorded period of at least 3 hours. This is not sleep-onset time.",12,400,Design.MUTED);
        RecordUi.heading(body,"Saved duration goals");Design.text(body,!data.goalsAvailable?"Goal history unavailable":data.goal.observed==0?"No comparable closed dates":GoalProgress.signed(data.goal.balance)+" across "+data.goal.observed+" observed dates",19,600,Design.INK);Design.text(body,data.goalsAvailable?data.goal.unknown+" missing goal dates · current plan is not applied to past dates":"Other statistics remain available.",12,400,Design.MUTED);PlanActivity.detail(body,"report","Review dated goals",null,null,()->startActivity(RecordUi.intent(this,GoalBankActivity.class).putExtra("goalRangeStart",data.range.start.toString()).putExtra("goalRangeEnd",data.range.end.toString())));
        RecordUi.heading(body,"Main-period start consistency");Design.text(body,data.startRange==null?"At least 2 main periods needed":RecordUi.duration(RhythmStats.displayDurationMillis(data.startRange))+" start-time range",20,600,Design.INK);Design.text(body,data.mainPeriods+" main periods · midnight wraps correctly",12,400,Design.MUTED);PlanActivity.detail(body,"moon","Explore recorded rhythm",null,null,()->startActivity(RecordUi.intent(this,SleepRhythmActivity.class)));
        RecordUi.heading(body,"Tag comparisons");if(data.associations.isEmpty())Design.text(body,"Need at least 3 main records with a tag and 3 without it.",13,400,Design.MUTED);else for(RecordInsights.Association association:data.associations)PlanActivity.detail(body,"tag",association.tag,association.with+" with · "+association.without+" without · association only",GoalProgress.signed(association.difference),()->startActivity(RecordUi.intent(this,TagManagementActivity.class).putExtra("tag",association.tag)));Design.text(body,"Mean recorded-duration difference. Other factors may explain it.",12,400,Design.MUTED);PlanActivity.detail(body,"tag","Explore all saved tags",null,null,()->startActivity(RecordUi.intent(this,TagManagementActivity.class)));
        RecordUi.heading(body,"About this view");Design.text(body,data.phone+" phone/legacy · "+data.manual+" manual · "+data.imported+" imported periods",12,400,Design.MUTED);if(data.interrupted>0)Design.text(body,data.interrupted+" interrupted periods; coverage may be incomplete.",12,500,Design.BROWN);Design.text(body,"Overlaps count once. Recorded duration includes unmarked awake time.",12,400,Design.MUTED);Design.space(body,12);Design.button(body,"Review saved records",true,()->startActivity(RecordUi.intent(this,HistoryActivity.class)));if(data.latestRecord>0){Design.button(body,"Recorded night score",false,()->startActivity(RecordUi.intent(this,RecordedNightScoreActivity.class).putExtra("record",data.latestRecord)));Design.button(body,"Open latest period",false,()->startActivity(RecordUi.intent(this,RecordReportActivity.class).putExtra("record",data.latestRecord)));}
    }
    @Override public void onSaveInstanceState(Bundle state){super.onSaveInstanceState(state);state.putInt("days",days);state.putInt("metric",metric);state.putBoolean("chosen",chosen);if(anchor!=null)state.putString("anchor",anchor.toString());}
    void awaitReaders(long millis)throws Exception{if(worker.isShutdown()){if(!worker.awaitTermination(millis,TimeUnit.MILLISECONDS))throw new TimeoutException("Insight reader busy");}else worker.submit(()->{}).get(millis,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){generation++;worker.shutdownNow();super.onDestroy();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus)RecordUi.lightBars(this);}
}
